import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';
import '../theme/app_colors.dart';

/// Lightweight, native Flutter rich content renderer for announcements & posts.
/// Automatically parses HTML blocks generated by TipTap / Quill / RichEditor:
/// - Paragraphs (<p>)
/// - Headings (<h1>, <h2>, <h3>)
/// - Lists (<ul>, <ol>, <li>)
/// - Blockquotes (<blockquote>)
/// - Tables (<table>, <tr>, <th>, <td>)
/// - Inline styling (<b>, <strong>, <i>, <em>, <u>, <s>, <strike>, <del>, <a href="...">)
class RichContentView extends StatelessWidget {
  final String content;
  final TextStyle? baseStyle;
  final Color linkColor;

  const RichContentView({
    super.key,
    required this.content,
    this.baseStyle,
    this.linkColor = const Color(0xFF2563EB),
  });

  /// Helper to clean raw HTML into plain text (e.g. for card snippets).
  static String stripHtml(String html) {
    if (html.isEmpty) return '';
    return html
        .replaceAll(RegExp(r'<br\s*/?>', caseSensitive: false), ' ')
        .replaceAll(RegExp(r'</p>', caseSensitive: false), ' ')
        .replaceAll(RegExp(r'</li>', caseSensitive: false), ' ')
        .replaceAll(RegExp(r'<[^>]*>'), '')
        .replaceAll('&nbsp;', ' ')
        .replaceAll('&amp;', '&')
        .replaceAll('&quot;', '"')
        .replaceAll('&#39;', "'")
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  static bool hasHtmlTags(String text) {
    return RegExp(r'<[a-z/][\s\S]*>', caseSensitive: false).hasMatch(text);
  }

  @override
  Widget build(BuildContext context) {
    final style = baseStyle ??
        const TextStyle(
          fontSize: 14,
          color: AppColors.gray700,
          height: 1.6,
        );

    if (!hasHtmlTags(content)) {
      return SelectableText(content, style: style);
    }

    final blocks = _parseBlocks(content);
    if (blocks.isEmpty) {
      return SelectableText(stripHtml(content), style: style);
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: blocks.map((b) => _renderBlock(context, b, style)).toList(),
    );
  }

  Widget _renderBlock(BuildContext context, _HtmlBlock block, TextStyle defaultStyle) {
    switch (block.type) {
      case _BlockType.heading:
        final double fontSize = block.level == 1 ? 20 : (block.level == 2 ? 17 : 15);
        final headingStyle = defaultStyle.copyWith(
          fontSize: fontSize,
          fontWeight: FontWeight.w800,
          color: AppColors.gray900,
          height: 1.35,
        );
        return Padding(
          padding: const EdgeInsets.only(top: 14, bottom: 6),
          child: Text.rich(
            TextSpan(children: _parseInlineSpans(block.innerHtml, headingStyle)),
          ),
        );

      case _BlockType.paragraph:
        return Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Text.rich(
            TextSpan(children: _parseInlineSpans(block.innerHtml, defaultStyle)),
          ),
        );

      case _BlockType.unorderedList:
        return Padding(
          padding: const EdgeInsets.only(left: 4, bottom: 10),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: block.listItems.map((li) {
              return Padding(
                padding: const EdgeInsets.only(bottom: 4),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('•  ', style: defaultStyle.copyWith(fontWeight: FontWeight.bold, color: AppColors.blue600)),
                    Expanded(
                      child: Text.rich(
                        TextSpan(children: _parseInlineSpans(li, defaultStyle)),
                      ),
                    ),
                  ],
                ),
              );
            }).toList(),
          ),
        );

      case _BlockType.orderedList:
        return Padding(
          padding: const EdgeInsets.only(left: 4, bottom: 10),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: block.listItems.asMap().entries.map((entry) {
              final idx = entry.key + 1;
              final li = entry.value;
              return Padding(
                padding: const EdgeInsets.only(bottom: 4),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(
                      width: 24,
                      child: Text('$idx. ', style: defaultStyle.copyWith(fontWeight: FontWeight.w700, color: AppColors.blue600)),
                    ),
                    Expanded(
                      child: Text.rich(
                        TextSpan(children: _parseInlineSpans(li, defaultStyle)),
                      ),
                    ),
                  ],
                ),
              );
            }).toList(),
          ),
        );

      case _BlockType.blockquote:
        final quoteStyle = defaultStyle.copyWith(
          fontStyle: FontStyle.italic,
          color: AppColors.gray600,
        );
        return Container(
          width: double.infinity,
          margin: const EdgeInsets.symmetric(vertical: 8),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
          decoration: const BoxDecoration(
            color: AppColors.gray50,
            borderRadius: BorderRadius.horizontal(right: Radius.circular(10)),
            border: Border(
              left: BorderSide(color: Color(0xFF0F2460), width: 3.5),
            ),
          ),
          child: Text.rich(
            TextSpan(children: _parseInlineSpans(block.innerHtml, quoteStyle)),
          ),
        );

      case _BlockType.table:
        return Container(
          margin: const EdgeInsets.symmetric(vertical: 8),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: AppColors.gray200),
          ),
          clipBehavior: Clip.antiAlias,
          child: Table(
            border: const TableBorder.symmetric(
              inside: BorderSide(color: AppColors.gray200, width: 0.8),
            ),
            children: block.tableRows.map((row) {
              return TableRow(
                decoration: BoxDecoration(
                  color: row.isHeader ? AppColors.gray100 : Colors.white,
                ),
                children: row.cells.map((cell) {
                  final cellStyle = defaultStyle.copyWith(
                    fontSize: 12.5,
                    fontWeight: row.isHeader ? FontWeight.bold : FontWeight.normal,
                    color: row.isHeader ? AppColors.gray900 : AppColors.gray700,
                  );
                  return Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                    child: Text.rich(
                      TextSpan(children: _parseInlineSpans(cell, cellStyle)),
                    ),
                  );
                }).toList(),
              );
            }).toList(),
          ),
        );

      case _BlockType.divider:
        return const Padding(
          padding: EdgeInsets.symmetric(vertical: 12),
          child: Divider(color: AppColors.gray200, height: 1),
        );
    }
  }

  List<_HtmlBlock> _parseBlocks(String html) {
    final blocks = <_HtmlBlock>[];

    // Normalize newlines
    String src = html.replaceAll('\r\n', '\n').replaceAll('\r', '\n');

    final blockRegex = RegExp(
      r'<(h[1-6]|p|ul|ol|blockquote|table|hr)([^>]*)>([\s\S]*?)<\/\1>|<(hr)\s*\/?>',
      caseSensitive: false,
    );

    int lastIndex = 0;
    for (final match in blockRegex.allMatches(src)) {
      // Check if there was plain text before this block
      if (match.start > lastIndex) {
        final preText = src.substring(lastIndex, match.start).trim();
        if (preText.isNotEmpty) {
          blocks.add(_HtmlBlock(type: _BlockType.paragraph, innerHtml: preText));
        }
      }

      final tag = (match.group(1) ?? match.group(4) ?? '').toLowerCase();
      final inner = match.group(3) ?? '';

      if (tag.startsWith('h')) {
        final level = int.tryParse(tag.substring(1)) ?? 2;
        blocks.add(_HtmlBlock(type: _BlockType.heading, innerHtml: inner.trim(), level: level));
      } else if (tag == 'p') {
        if (inner.trim().isNotEmpty) {
          blocks.add(_HtmlBlock(type: _BlockType.paragraph, innerHtml: inner.trim()));
        }
      } else if (tag == 'ul') {
        final items = _extractListItems(inner);
        if (items.isNotEmpty) {
          blocks.add(_HtmlBlock(type: _BlockType.unorderedList, listItems: items));
        }
      } else if (tag == 'ol') {
        final items = _extractListItems(inner);
        if (items.isNotEmpty) {
          blocks.add(_HtmlBlock(type: _BlockType.orderedList, listItems: items));
        }
      } else if (tag == 'blockquote') {
        blocks.add(_HtmlBlock(type: _BlockType.blockquote, innerHtml: inner.trim()));
      } else if (tag == 'hr') {
        blocks.add(_HtmlBlock(type: _BlockType.divider));
      } else if (tag == 'table') {
        final rows = _parseTableRows(inner);
        if (rows.isNotEmpty) {
          blocks.add(_HtmlBlock(type: _BlockType.table, tableRows: rows));
        }
      }

      lastIndex = match.end;
    }

    if (lastIndex < src.length) {
      final remainder = src.substring(lastIndex).trim();
      if (remainder.isNotEmpty) {
        blocks.add(_HtmlBlock(type: _BlockType.paragraph, innerHtml: remainder));
      }
    }

    return blocks;
  }

  List<String> _extractListItems(String listHtml) {
    final items = <String>[];
    final liRegex = RegExp(r'<li[^>]*>([\s\S]*?)<\/li>', caseSensitive: false);
    for (final match in liRegex.allMatches(listHtml)) {
      final text = match.group(1)?.trim();
      if (text != null && text.isNotEmpty) {
        items.add(text);
      }
    }
    return items;
  }

  List<_TableRowData> _parseTableRows(String tableHtml) {
    final rows = <_TableRowData>[];
    final trRegex = RegExp(r'<tr[^>]*>([\s\S]*?)<\/tr>', caseSensitive: false);
    final cellRegex = RegExp(r'<(td|th)[^>]*>([\s\S]*?)<\/\1>', caseSensitive: false);

    for (final trMatch in trRegex.allMatches(tableHtml)) {
      final trInner = trMatch.group(1) ?? '';
      final cells = <String>[];
      bool isHeaderRow = false;

      for (final cMatch in cellRegex.allMatches(trInner)) {
        final cellTag = (cMatch.group(1) ?? '').toLowerCase();
        if (cellTag == 'th') isHeaderRow = true;
        cells.add(cMatch.group(2)?.trim() ?? '');
      }

      if (cells.isNotEmpty) {
        rows.add(_TableRowData(cells: cells, isHeader: isHeaderRow));
      }
    }
    return rows;
  }

  List<InlineSpan> _parseInlineSpans(String rawHtml, TextStyle currentStyle) {
    final spans = <InlineSpan>[];

    // Normalize breaks
    String text = rawHtml
        .replaceAll(RegExp(r'<br\s*/?>', caseSensitive: false), '\n')
        .replaceAll('&nbsp;', ' ')
        .replaceAll('&amp;', '&')
        .replaceAll('&quot;', '"')
        .replaceAll('&#39;', "'")
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>');

    final tagRegex = RegExp(
      r'<(strong|b|em|i|u|s|strike|del|a)([^>]*)>([\s\S]*?)<\/\1>',
      caseSensitive: false,
    );

    int lastIndex = 0;
    for (final match in tagRegex.allMatches(text)) {
      if (match.start > lastIndex) {
        final plainBefore = text.substring(lastIndex, match.start);
        spans.add(TextSpan(text: _stripRemainingTags(plainBefore), style: currentStyle));
      }

      final tag = (match.group(1) ?? '').toLowerCase();
      final attrs = match.group(2) ?? '';
      final inner = match.group(3) ?? '';

      TextStyle subStyle = currentStyle;
      if (tag == 'strong' || tag == 'b') {
        subStyle = subStyle.copyWith(fontWeight: FontWeight.bold);
      } else if (tag == 'em' || tag == 'i') {
        subStyle = subStyle.copyWith(fontStyle: FontStyle.italic);
      } else if (tag == 'u') {
        subStyle = subStyle.copyWith(decoration: TextDecoration.underline);
      } else if (tag == 's' || tag == 'strike' || tag == 'del') {
        subStyle = subStyle.copyWith(decoration: TextDecoration.lineThrough);
      } else if (tag == 'a') {
        final hrefMatch = RegExp(r'''href=["']([^"']+)["']''', caseSensitive: false).firstMatch(attrs);
        final url = hrefMatch?.group(1);
        subStyle = subStyle.copyWith(
          color: linkColor,
          decoration: TextDecoration.underline,
          fontWeight: FontWeight.w600,
        );

        TapGestureRecognizer? recognizer;
        if (url != null && url.isNotEmpty) {
          recognizer = TapGestureRecognizer()
            ..onTap = () async {
              final uri = Uri.tryParse(url);
              if (uri != null && await canLaunchUrl(uri)) {
                await launchUrl(uri, mode: LaunchMode.externalApplication);
              }
            };
        }

        spans.addAll(_parseInlineSpans(inner, subStyle).map((span) {
          if (span is TextSpan) {
            return TextSpan(
              text: span.text,
              children: span.children,
              style: span.style,
              recognizer: recognizer,
            );
          }
          return span;
        }));

        lastIndex = match.end;
        continue;
      }

      // Recurse for nested inline tags
      spans.addAll(_parseInlineSpans(inner, subStyle));
      lastIndex = match.end;
    }

    if (lastIndex < text.length) {
      final plainAfter = text.substring(lastIndex);
      spans.add(TextSpan(text: _stripRemainingTags(plainAfter), style: currentStyle));
    }

    return spans;
  }

  String _stripRemainingTags(String input) {
    return input.replaceAll(RegExp(r'<[^>]*>'), '');
  }
}

enum _BlockType {
  heading,
  paragraph,
  unorderedList,
  orderedList,
  blockquote,
  table,
  divider,
}

class _HtmlBlock {
  final _BlockType type;
  final String innerHtml;
  final int level;
  final List<String> listItems;
  final List<_TableRowData> tableRows;

  _HtmlBlock({
    required this.type,
    this.innerHtml = '',
    this.level = 2,
    this.listItems = const [],
    this.tableRows = const [],
  });
}

class _TableRowData {
  final List<String> cells;
  final bool isHeader;

  _TableRowData({required this.cells, this.isHeader = false});
}
